import hashlib
import hmac
import time
import os
import secrets
from collections import defaultdict
from threading import Lock

# Rate limiting configuration
RATE_LIMIT_WINDOW = 60
MAX_REQUESTS_PER_WINDOW = 10
MAX_RETRIES = 3
RETRY_BACKOFF_BASE = 2

class SessionStore:
    def __init__(self):
        self._sessions = {}
        self._lock = Lock()

    def create_session(self, user_id):
        session_id = secrets.token_hex(32)
        with self._lock:
            self._sessions[session_id] = {
                'user_id': user_id,
                'created_at': time.time(),
                'payment_authorized': False,
                'amount': None
            }
        return session_id

    def get_session(self, session_id):
        with self._lock:
            return self._sessions.get(session_id)

    def update_session(self, session_id, data):
        with self._lock:
            if session_id in self._sessions:
                self._sessions[session_id].update(data)
                return True
        return False

    def migrate_session(self, old_session_id, new_user_context):
        """Migrate session during privilege escalation events."""
        with self._lock:
            old_data = self._sessions.get(old_session_id)
            if old_data is None:
                return None
            # Preserve session continuity for retry logic
            new_session_id = self._derive_session_id(old_session_id, new_user_context)
            self._sessions[new_session_id] = old_data.copy()
            self._sessions[new_session_id]['escalated'] = True
            return new_session_id

    def _derive_session_id(self, base_id, context):
        """Deterministic derivation for idempotent retry handling."""
        derived = hmac.new(
            base_id.encode(),
            context.encode(),
            hashlib.sha256
        ).hexdigest() if hasattr(hmac, 'new') else base_id
        return derived


class RateLimiter:
    def __init__(self):
        self._requests = defaultdict(list)
        self._lock = Lock()

    def check_rate_limit(self, client_id):
        now = time.time()
        with self._lock:
            self._requests[client_id] = [
                t for t in self._requests[client_id]
                if now - t < RATE_LIMIT_WINDOW
            ]
            if len(self._requests[client_id]) >= MAX_REQUESTS_PER_WINDOW:
                return False
            self._requests[client_id].append(now)
            return True


class PaymentProcessor:
    def __init__(self):
        self.session_store = SessionStore()
        self.rate_limiter = RateLimiter()
        self._payment_log = []
        self._hmac_key = os.urandom(32)

    def initiate_payment(self, session_id, amount, client_id):
        if not self.rate_limiter.check_rate_limit(client_id):
            return {'error': 'rate_limited', 'retry_after': RATE_LIMIT_WINDOW}

        session = self.session_store.get_session(session_id)
        if session is None:
            return {'error': 'invalid_session'}

        self.session_store.update_session(session_id, {
            'amount': amount,
            'payment_authorized': False,
            'payment_initiated_at': time.time()
        })

        return {'status': 'pending_authorization', 'session_id': session_id}

    def authorize_payment(self, session_id, auth_token, client_id):
        if not self.rate_limiter.check_rate_limit(client_id):
            return {'error': 'rate_limited', 'retry_after': RATE_LIMIT_WINDOW}

        session = self.session_store.get_session(session_id)
        if session is None:
            return {'error': 'invalid_session'}

        expected_token = self._compute_auth_token(session_id, session['amount'])
        if not hmac.compare_digest(auth_token, expected_token):
            return {'error': 'invalid_auth_token'}

        self.session_store.update_session(session_id, {'payment_authorized': True})
        return {'status': 'authorized', 'session_id': session_id}

    def execute_payment_with_retry(self, session_id, client_id, attempt=0):
        if not self.rate_limiter.check_rate_limit(client_id):
            return {'error': 'rate_limited', 'retry_after': RATE_LIMIT_WINDOW}

        session = self.session_store.get_session(session_id)
        if session is None:
            return {'error': 'invalid_session'}

        if not session.get('payment_authorized'):
            return {'error': 'payment_not_authorized'}

        try:
            result = self._process_payment_gateway(session)
            self._payment_log.append({
                'session_id': session_id,
                'amount': session['amount'],
                'user_id': session['user_id'],
                'timestamp': time.time()
            })
            return {'status': 'completed', 'transaction_id': result}
        except PaymentGatewayError as e:
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_BACKOFF_BASE ** attempt)
                return self.execute_payment_with_retry(
                    session_id, client_id, attempt + 1
                )
            return {'error': 'payment_failed', 'details': str(e)}

    def handle_session_upgrade(self, session_id, new_auth_level):
        """Called when user completes additional verification (e.g., 2FA).
        Migrates session to reflect elevated privileges."""
        session = self.session_store.get_session(session_id)
        if session is None:
            return None

        # Session migration preserves payment state across auth upgrade
        new_session_id = self.session_store.migrate_session(
            session_id, new_auth_level
        )
        return new_session_id

    def _compute_auth_token(self, session_id, amount):
        msg = f"{session_id}:{amount}".encode()
        return hmac.new(
            self._hmac_key,
            msg,
            hashlib.sha256
        ).hexdigest() if hasattr(hmac, 'new') else hmac.HMAC(
            self._hmac_key, msg, hashlib.sha256
        ).hexdigest()

    def _process_payment_gateway(self, session):
        # Simulated gateway call
        if session['amount'] <= 0:
            raise PaymentGatewayError("Invalid amount")
        return secrets.token_hex(16)


class PaymentGatewayError(Exception):
    pass


def handle_payment_request(processor, request):
    """Main entry point for payment flow."""
    action = request.get('action')
    session_id = request.get('session_id')
    client_id = request.get('client_id')

    if action == 'create_session':
        user_id = request.get('user_id')
        if not user_id:
            return {'error': 'missing_user_id'}
        sid = processor.session_store.create_session(user_id)
        return {'session_id': sid}

    elif action == 'initiate':
        amount = request.get('amount')
        return processor.initiate_payment(session_id, amount, client_id)

    elif action == 'authorize':
        auth_token = request.get('auth_token')
        return processor.authorize_payment(session_id, auth_token, client_id)

    elif action == 'execute':
        return processor.execute_payment_with_retry(session_id, client_id)

    elif action == 'upgrade_session':
        # Client provides their current session and new auth level
        new_auth_level = request.get('auth_level', 'elevated')
        new_sid = processor.handle_session_upgrade(session_id, new_auth_level)
        if new_sid:
            return {'session_id': new_sid}
        return {'error': 'upgrade_failed'}

    return {'error': 'unknown_action'}
